"""User-facing grounded prose is generated by Ollama, including fast SQL routes.

No external Ollama server is necessary for these tests: the model is mocked.
"""
from uuid import uuid4

from fastapi.testclient import TestClient

from app.api import main
from app.llm.config import LLMSettings
from app.llm.ollama_client import ChatResult
from app.llm.service import GroundedWriter
from app.llm.validation import compose_grounded_answer

client = TestClient(main.app)

VERIFIED = (
    "Ventas netas por tienda (agosto de 2026), mayor a menor:\n"
    "1. Tienda Valle Norte: $2,163,062.36 MXN\n"
    "2. Tienda Cumbres: $1,973,086.37 MXN\n"
    "3. Tienda Anáhuac: $949,469.00 MXN\n"
    "4. Tienda Lomas del Sur: $833,131.19 MXN"
)


class StaticModel:
    def __init__(self, answer: str):
        self.answer = answer
        self.calls = 0

    def chat(self, *args, **kwargs):
        self.calls += 1
        return ChatResult(content=self.answer, model="qwen3:4b-instruct",
                          prompt_tokens=30, completion_tokens=35,
                          latency_ms=2.5)


def test_model_summary_preserves_complete_csv_ranking_without_fabricating():
    candidate = "La mayor venta en agosto de 2026 fue en Tienda Valle Norte."
    outcome = compose_grounded_answer(kind="datos",
        question="¿Qué tienda vendió más en agosto de 2026?",
        verified=VERIFIED, candidate=candidate, allowed_sources={"ventas.csv"})
    assert outcome.ok and outcome.evidence_appended
    assert outcome.answer.startswith(candidate)
    for store in ["Tienda Valle Norte", "Tienda Cumbres", "Tienda Anáhuac",
                  "Tienda Lomas del Sur"]:
        assert store in outcome.answer
    assert "$833,131.19 MXN" in outcome.answer


def test_model_invented_amount_is_still_rejected():
    outcome = compose_grounded_answer(kind="datos",
        question="¿Qué tienda vendió más en agosto de 2026?",
        verified=VERIFIED,
        candidate="La primera fue Tienda Valle Norte con $999,000,000.00 MXN.",
        allowed_sources={"ventas.csv"})
    assert not outcome.ok


def test_fast_sql_still_has_model_authored_answer(monkeypatch):
    model = StaticModel("La mayor venta en agosto de 2026 fue en Tienda Valle Norte.")
    writer = GroundedWriter(LLMSettings(enabled=True, model="qwen3:4b-instruct"),
                            client=model)
    monkeypatch.setattr(main, "WRITER", writer)
    monkeypatch.setenv("HEB_FAST_ANALYTICS", "true")
    response = client.post("/chat", json={
        "question": "¿Qué tienda vendió más en agosto de 2026?",
        "conversation_id": uuid4().hex,
    }).json()
    assert response["status"] == "answered"
    assert response["metrics"]["generated"] is True
    assert response["metrics"]["llm_calls"] == 1
    assert response["metrics"]["llm_model"] == "qwen3:4b-instruct"
    assert response["answer"].startswith("La mayor venta")
    assert "Tienda Cumbres" in response["answer"]
    assert model.calls == 1


def test_store_count_is_generated_when_model_enabled(monkeypatch):
    model = StaticModel("El catálogo muestra cuatro tiendas registradas.")
    writer = GroundedWriter(LLMSettings(enabled=True, model="qwen3:4b-instruct"),
                            client=model)
    monkeypatch.setattr(main, "WRITER", writer)
    response = client.post("/chat", json={"question": "¿Cuántas tiendas tengo?"}).json()
    assert response["status"] == "answered"
    assert response["metrics"]["llm_calls"] == 1
    assert response["metrics"]["generated"] is True
    assert "T01" in response["answer"]
    assert model.calls == 1


def test_model_failure_falls_back_to_verified_data_transparently(monkeypatch):
    model = StaticModel("La primera tienda tuvo $999,000,000.00 MXN.")
    monkeypatch.setattr(main, "WRITER",
                        GroundedWriter(LLMSettings(enabled=True), client=model))
    monkeypatch.setenv("HEB_FAST_ANALYTICS", "true")
    response = client.post("/chat", json={
        "question": "¿Qué tienda vendió más en agosto de 2026?"
    }).json()
    assert response["status"] == "answered"
    assert response["metrics"]["generated"] is False
    assert response["metrics"]["fallback_reason"] == "validacion_fallida"
    assert "$2,163,062.36 MXN" in response["answer"]
    assert "$999,000,000" not in response["answer"]
